before.lib/counter.ex:
defmodule Counter do
  @moduledoc "A counter process. Only start_link/0, add/2 and value/1 are public behavior."
  def start_link, do: Agent.start_link(fn -> %{value: 0} end)
  def add(pid, amount), do: Agent.update(pid, &%{&1 | value: &1.value + amount})
  def value(pid), do: Agent.get(pid, & &1.value)
end

